python3 - <<'EOF'
import xml.etree.ElementTree as ET

NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

tree = ET.parse('/work/output/artifacts/skill-bpmn-terminate/TerminateParallel.bpmn')
root = tree.getroot()

errors = []

# 1. Root is definitions with BPMN namespace
assert 'definitions' in root.tag, "Root is not definitions"

# Collect all IDs
all_ids = {el.get('id') for el in root.iter() if el.get('id')}

# 2. BPMNDiagram exists with shapes/edges
diagrams = root.findall('.//bpmndi:BPMNDiagram', NS)
assert len(diagrams) == 1, f"Expected 1 BPMNDiagram, got {len(diagrams)}"

shapes = {s.get('bpmnElement') for s in root.findall('.//bpmndi:BPMNShape', NS)}
edges  = {e.get('bpmnElement') for e in root.findall('.//bpmndi:BPMNEdge', NS)}

proc = root.find('bpmn:process', NS)
flow_nodes = [el for el in proc if el.tag not in (
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow',
    '{http://www.omg.org/spec/BPMN/20100524/MODEL}extensionElements',
)]
flows = proc.findall('bpmn:sequenceFlow', NS)

node_ids = [n.get('id') for n in flow_nodes]
flow_ids  = [f.get('id') for f in flows]

for nid in node_ids:
    if nid not in shapes:
        errors.append(f"Node {nid} has no BPMNShape")
for fid in flow_ids:
    if fid not in edges:
        errors.append(f"Flow {fid} has no BPMNEdge")

# 3. Every ref resolves
for flow in flows:
    for attr in ('sourceRef', 'targetRef'):
        ref = flow.get(attr)
        if ref not in all_ids:
            errors.append(f"Flow {flow.get('id')} {attr}={ref} not found")

# 4. Parallel gateway: no conditions on outgoing flows
for gw in proc.findall('bpmn:parallelGateway', NS):
    for out in gw.findall('bpmn:outgoing', NS):
        fid = out.text.strip()
        for flow in flows:
            if flow.get('id') == fid:
                cond = flow.find('bpmn:conditionExpression', NS)
                if cond is not None:
                    errors.append(f"Parallel gateway {gw.get('id')} has condition on {fid}")

# 5. No activity/event has more than one incoming flow
for node in flow_nodes:
    inc = node.findall('bpmn:incoming', NS)
    if len(inc) > 1:
        errors.append(f"Node {node.get('id')} has {len(inc)} incoming flows (fake join?)")

# 6. terminateEventDefinition is only on endEvent
for el in proc.iter():
    tag = el.tag.split('}')[-1] if '}' in el.tag else el.tag
    for child in el:
        ctag = child.tag.split('}')[-1] if '}' in child.tag else child.tag
        if ctag == 'terminateEventDefinition' and tag != 'endEvent':
            errors.append(f"terminateEventDefinition on {tag} (only allowed on endEvent)")

# Check terminate end event exists
term_ends = [el for el in proc.findall('bpmn:endEvent', NS)
             if el.find('bpmn:terminateEventDefinition', NS) is not None]
assert len(term_ends) == 1, f"Expected 1 terminate end event, got {len(term_ends)}"

if errors:
    for e in errors:
        print("ERROR:", e)
else:
    print("STRUCTURAL CHECK: VALID")
    print(f"  Nodes: {node_ids}")
    print(f"  Flows: {flow_ids}")
    print(f"  Shapes: {sorted(shapes)}")
    print(f"  Edges:  {sorted(edges)}")
    print(f"  Terminate end events: {[e.get('id') for e in term_ends]}")
EOF

